window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cdc20f812a0f5e26"]={"versions": [{"id": "FIG-cdc20f812a0f5e26", "releases": ["R1.5.1", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Pseudocode-Darstellung einer Arbitrierungsregel innerhalb des Funktionsbereichs Health Monitoring (AUTOSAR Adaptive Platform). Das Diagramm veranschaulicht das logische Auswertungsmuster (Arbitration Rule) zur Überprüfung konfigurierter Zustände auf überwachten Kanälen und zur anschließenden Aktionsauslösung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die übergeordnete Entität ist das Modul <code>HEALTH MONITORING</code>. Darin gekapselt ist die Komponente bzw. Logik <code>Arbitration Rule</code>, die auf mindestens zwei Zustandsquellen zugreift:</p>\n<ul class=\"fig-list\"><li><code>HealthChannel1</code> (überprüft auf Zustand <code>Status_A</code>)\n</li><li><code>HealthChannel2</code> (überprüft auf Zustand <code>Status_B</code>)\n</li></ul>\n<p class=\"fig-p\">Als Schnittstellen- bzw. Ausführungsergebnisse sind zwei Aktionspfade definiert:</p>\n<ul class=\"fig-list\"><li><code>True Action</code> (wird bei erfüllter Gesamtbedingung ausgelöst)\n</li><li><code>False Action</code> (wird bei nicht erfüllter Bedingung ausgelöst)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Auswertung erfolgt in Form einer bedingten Verzweigung:</p>\n<ol class=\"fig-list\"><li>Prüfung des logischen Gesamtausdrucks: <code>HealthChannel1 = Status_A &amp;&amp; HealthChannel2 = Status_B</code>. Beide Teilbedingungen müssen über den logischen UND-Operator (<code>&amp;&amp;</code>) gleichzeitig wahr sein.\n</li><li>Wenn die Auswertung <code>true</code> ergibt, erfolgt der Aufruf von <code>Execute the True Action</code>.\n</li><li>Andernfalls (<code>else</code>) führt der Pfad zur Ausführung von <code>Execute the False Action</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Darstellung der Regelauswertung gemäß Spezifikationsabschnitt zur Health-Monitoring-Arbitrierung. Implementierungen müssen konfigurierbare logische Ausdrücke unterstützen, die Zustände definierter HealthChannels abfragen und deterministisch die zugehörige Aktionsliste (<code>ActionList</code>) für den positiven bzw. negativen Fall triggern. Die konkrete Speicherung, Syntax der Regeldefinition sowie der Triggerzeitpunkt (bei Statusänderung oder zyklisch im Main-Task) werden durch die Konfiguration und Spezifikation bestimmt.</p>"}, {"id": "FIG-079f58cd26519d52", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Pseudocode-Darstellung einer Arbitrierungsregel innerhalb des Funktionsbereichs Health Monitoring (AUTOSAR Adaptive Platform). Das Diagramm veranschaulicht das logische Auswertungsmuster (Arbitration Rule) zur Überprüfung konfigurierter Zustände auf überwachten Kanälen und zur anschließenden Aktionsauslösung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die übergeordnete Entität ist das Modul <code>HEALTH MONITORING</code>. Darin gekapselt ist die Komponente bzw. Logik <code>Arbitration Rule</code>, die auf mindestens zwei Zustandsquellen zugreift:</p>\n<ul class=\"fig-list\"><li><code>HealthChannel1</code> (überprüft auf Zustand <code>Status_A</code>)\n</li><li><code>HealthChannel2</code> (überprüft auf Zustand <code>Status_B</code>)\n</li></ul>\n<p class=\"fig-p\">Als Schnittstellen- bzw. Ausführungsergebnisse sind zwei Aktionspfade definiert:</p>\n<ul class=\"fig-list\"><li><code>True Action</code> (wird bei erfüllter Gesamtbedingung ausgelöst)\n</li><li><code>False Action</code> (wird bei nicht erfüllter Bedingung ausgelöst)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Auswertung erfolgt in Form einer bedingten Verzweigung:</p>\n<ol class=\"fig-list\"><li>Prüfung des logischen Gesamtausdrucks: <code>HealthChannel1 = Status_A &amp;&amp; HealthChannel2 = Status_B</code>. Beide Teilbedingungen müssen über den logischen UND-Operator (<code>&amp;&amp;</code>) gleichzeitig wahr sein.\n</li><li>Wenn die Auswertung <code>true</code> ergibt, erfolgt der Aufruf von <code>Execute the True Action</code>.\n</li><li>Andernfalls (<code>else</code>) führt der Pfad zur Ausführung von <code>Execute the False Action</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarische Darstellung der Regelauswertung gemäß Spezifikationsabschnitt zur Health-Monitoring-Arbitrierung. Implementierungen müssen konfigurierbare logische Ausdrücke unterstützen, die Zustände definierter HealthChannels abfragen und deterministisch die zugehörige Aktionsliste (<code>ActionList</code>) für den positiven bzw. negativen Fall triggern. Die konkrete Speicherung, Syntax der Regeldefinition sowie der Triggerzeitpunkt (bei Statusänderung oder zyklisch im Main-Task) werden durch die Konfiguration und Spezifikation bestimmt.</p>"}], "trans": [{"from": "FIG-cdc20f812a0f5e26", "to": "FIG-079f58cd26519d52", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
